import{_ as a,o as s,c as i,a2 as e}from"./chunks/framework.BZO4qERu.js";const k=JSON.parse('{"title":"Задачи по расписанию","description":"","frontmatter":{},"headers":[],"relativePath":"ru/guides/schedule.md","filePath":"ru/guides/schedule.md","lastUpdated":1792323081000}'),n={name:"ru/guides/schedule.md"};function o(l,t,r,d,h,p){return s(),i("div",null,[...t[0]||(t[0]=[e(`<h1 id="задачи-по-расписанию" tabindex="-1">Задачи по расписанию <a class="header-anchor" href="#задачи-по-расписанию" aria-label="Permalink to &quot;Задачи по расписанию&quot;">​</a></h1><p>Задачи по расписанию позволяют автоматизировать повторяющиеся действия Bot с помощью cron-выражений. Это удобно для периодических отчётов, проверки внешних данных, обслуживания — любой рутинной задачи без ручного вмешательства.</p><h2 id="концепция-автоматизация-на-cron" tabindex="-1">Концепция: автоматизация на cron <a class="header-anchor" href="#концепция-автоматизация-на-cron" aria-label="Permalink to &quot;Концепция: автоматизация на cron&quot;">​</a></h2><p><strong>Schedule</strong> (расписание) — это правило на основе cron, привязанное к конкретному Bot. Когда расписание срабатывает, оно передаёт агенту команду, и тот выполняет её, используя доступные инструменты, навыки и контекст. Результаты Bot может доставить в любой подключённый канал.</p><hr><h2 id="поля-расписания" tabindex="-1">Поля расписания <a class="header-anchor" href="#поля-расписания" aria-label="Permalink to &quot;Поля расписания&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Поле</th><th>Описание</th></tr></thead><tbody><tr><td><strong>Name</strong></td><td>Отображаемое имя задачи (например, «Утренняя сводка новостей»).</td></tr><tr><td><strong>Description</strong></td><td>Краткое объяснение, что делает задача.</td></tr><tr><td><strong>Pattern</strong></td><td>Cron-выражение, задающее, когда задача выполняется (например, <code>0 9 * * *</code> — ежедневно в 9:00).</td></tr><tr><td><strong>Command</strong></td><td>Инструкция на естественном языке, отправляемая агенту при срабатывании расписания (например, «Собери главные технические новости за сегодня и отправь их в канал Telegram»).</td></tr><tr><td><strong>Enabled</strong></td><td>Активно ли расписание сейчас.</td></tr><tr><td><strong>Max Calls</strong></td><td>Необязательный предел общего числа выполнений. Оставьте пустым, чтобы не ограничивать.</td></tr><tr><td><strong>Current Calls</strong></td><td>Сколько раз это расписание уже сработало.</td></tr></tbody></table><hr><h2 id="справка-по-шаблонам-cron" tabindex="-1">Справка по шаблонам cron <a class="header-anchor" href="#справка-по-шаблонам-cron" aria-label="Permalink to &quot;Справка по шаблонам cron&quot;">​</a></h2><p>Поле <code>pattern</code> использует стандартный синтаксис cron из пяти полей. Оно вычисляется в часовом поясе Bot — поле <strong>Timezone</strong> на вкладке <strong>General</strong> Bot; если оно не задано, используется серверная настройка <code>timezone</code> верхнего уровня (по умолчанию <code>UTC</code>).</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌───────────── minute (0–59)</span></span>
<span class="line"><span>│ ┌───────────── hour (0–23)</span></span>
<span class="line"><span>│ │ ┌───────────── day of month (1–31)</span></span>
<span class="line"><span>│ │ │ ┌───────────── month (1–12)</span></span>
<span class="line"><span>│ │ │ │ ┌───────────── day of week (0–6, Sun=0)</span></span>
<span class="line"><span>│ │ │ │ │</span></span>
<span class="line"><span>* * * * *</span></span></code></pre></div><p><strong>Частые примеры:</strong></p><table tabindex="0"><thead><tr><th>Шаблон</th><th>Значение</th></tr></thead><tbody><tr><td><code>0 9 * * *</code></td><td>Каждый день в 9:00</td></tr><tr><td><code>*/30 * * * *</code></td><td>Каждые 30 минут</td></tr><tr><td><code>0 0 * * 1</code></td><td>Каждый понедельник в полночь</td></tr><tr><td><code>0 8,20 * * *</code></td><td>Каждый день в 8:00 и 20:00</td></tr><tr><td><code>0 0 1 * *</code></td><td>Первого числа каждого месяца в полночь</td></tr></tbody></table><hr><h2 id="просмотр-расписании" tabindex="-1">Просмотр расписаний <a class="header-anchor" href="#просмотр-расписании" aria-label="Permalink to &quot;Просмотр расписаний&quot;">​</a></h2><ol><li>Перейдите на страницу <strong>Detail Page</strong> нужного Bot.</li><li>Выберите вкладку <strong>Schedule</strong>.</li><li>Список показывает все расписания этого Bot: имя, cron-шаблон, состояние включения и счётчики выполнений.</li><li>Нажмите <strong>Refresh</strong>, чтобы перезагрузить список.</li></ol><hr><h2 id="создание-расписании" tabindex="-1">Создание расписаний <a class="header-anchor" href="#создание-расписании" aria-label="Permalink to &quot;Создание расписаний&quot;">​</a></h2><p>Расписания создаются в основном двумя способами:</p><h3 id="через-bot-в-разговоре" tabindex="-1">Через Bot (в разговоре) <a class="header-anchor" href="#через-bot-в-разговоре" aria-label="Permalink to &quot;Через Bot (в разговоре)&quot;">​</a></h3><p>У самого Bot есть инструмент <code>schedule</code>. Можно попросить его создать расписание естественным языком:</p><blockquote><p>«Создай расписание „Daily Digest“, которое каждый день в 8 утра присылает мне сводку вчерашней активности в репозитории».</p></blockquote><p>Bot сам переведёт это в cron-выражение и зарегистрирует расписание.</p><h3 id="через-api" tabindex="-1">Через API <a class="header-anchor" href="#через-api" aria-label="Permalink to &quot;Через API&quot;">​</a></h3><p>Расписания можно создавать и программно, через REST API:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /api/bots/{bot_id}/schedule</span></span></code></pre></div><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Daily Digest&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;description&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Summarize repository activity every morning&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;pattern&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0 8 * * *&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;command&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Summarize yesterday&#39;s repository activity and send the result to Telegram.&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;enabled&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;max_calls&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">null</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><hr><h2 id="как-проходит-выполнение" tabindex="-1">Как проходит выполнение <a class="header-anchor" href="#как-проходит-выполнение" aria-label="Permalink to &quot;Как проходит выполнение&quot;">​</a></h2><p>Когда расписание срабатывает:</p><ol><li>Cron-сервис запускает расписание.</li><li>Счётчик <code>current_calls</code> увеличивается.</li><li>Если <code>max_calls</code> задан и достигнут, расписание автоматически отключается.</li><li>Агент получает <code>command</code> вместе с контекстом расписания.</li><li>Агент выполняет команду своими инструментами (например, веб-поиск, чтение файла, отправка сообщения).</li><li>Результаты могут быть доставлены в любой подключённый канал.</li></ol>`,31)])])}const u=a(n,[["render",o]]);export{k as __pageData,u as default};
